[package]
name = "vector"
version = "0.57.0"
authors = ["Vector Contributors <vector@datadoghq.com>"]
edition = "2024"
description = "A lightweight and ultra-fast tool for building observability pipelines"
homepage = "https://vector.dev"
license = "MPL-2.0"
readme = "README.md"
publish = false
default-run = "vector"
autobenches = false # our benchmarks are not runnable on their own either way
# Minimum supported rust version
# See docs/DEVELOPING.md for policy
rust-version = "1.95"

[[bin]]
name = "vector"
test = false
bench = false

[[bin]]
name = "secret-backend-example"
path = "src/config/loading/secret_backend_example.rs"
test = false
bench = false
required-features = ["secret-backend-example"]

[[test]]
name = "integration"
path = "tests/integration/lib.rs"

[[test]]
name = "e2e"
path = "tests/e2e/mod.rs"

[[test]]
name = "vector_api"
path = "tests/vector_api/lib.rs"
required-features = ["vector-api-tests"]

[profile.release]
debug = false # Do not include debug symbols in the executable.
codegen-units = 1
lto = "fat"

[profile.bench]
debug = true

[lints]
workspace = true

[package.metadata.deb]
name = "vector"
section = "admin"
maintainer-scripts = "distribution/debian/scripts/"
conf-files = ["/etc/default/vector"]
assets = [
  ["target/release/vector", "/usr/bin/", "755"],
  ["config/vector.yaml", "/usr/share/vector/examples/vector.yaml", "644"],
  ["config/examples/*", "/etc/vector/examples/", "644"],
  ["distribution/systemd/vector.service", "/lib/systemd/system/vector.service", "644"],
  ["distribution/systemd/vector.default", "/etc/default/vector", "600"],
  ["licenses/*", "/usr/share/vector/licenses/", "644"],
  ["NOTICE", "/usr/share/vector/NOTICE", "644"],
  ["LICENSE-3rdparty.csv", "/usr/share/vector/LICENSE-3rdparty.csv", "644"],
]
license-file = ["target/debian-license.txt"]
extended-description-file = "target/debian-extended-description.txt"
recommends = "datadog-signing-keys (>= 1:1.4.0)"

[package.metadata.deb.systemd-units]
unit-scripts = "distribution/systemd/"
enable = false
start = false

# libc requirements are defined by `cross`
# https://github.com/rust-embedded/cross#supported-targets
# Though, it seems like aarch64 libc is actually 2.18 and not 2.19
[package.metadata.deb.variants.arm-unknown-linux-gnueabi]
depends = "libc6 (>= 2.15)"

[package.metadata.deb.variants.armv7-unknown-linux-gnueabihf]
depends = "libc6 (>= 2.15)"

[package.metadata.deb.variants.x86_64-unknown-linux-gnu]
depends = "libc6 (>= 2.15)"

[package.metadata.deb.variants.x86_64-unknown-linux-musl]
depends = ""

[package.metadata.deb.variants.aarch64-unknown-linux-gnu]
depends = "libc6 (>= 2.18)"

[package.metadata.deb.variants.aarch64-unknown-linux-musl]
depends = ""

[workspace]
members = [
  ".",
  "lib/codecs",
  "lib/dnsmsg-parser",
  "lib/docs-renderer",
  "lib/fakedata",
  "lib/file-source",
  "lib/file-source-common",
  "lib/k8s-e2e-tests",
  "lib/k8s-test-framework",
  "lib/loki-logproto",
  "lib/prometheus-parser",
  "lib/opentelemetry-proto",
  "lib/tracing-limit",
  "lib/vector-api-client",
  "lib/vector-buffers",
  "lib/vector-common",
  "lib/vector-common-macros",
  "lib/vector-config",
  "lib/vector-config-common",
  "lib/vector-config-macros",
  "lib/vector-core",
  "lib/vector-lib",
  "lib/vector-lookup",
  "lib/vector-stream",
  "lib/vector-tap",
  "lib/vector-top",
  "lib/vector-vrl/category",
  "lib/vector-vrl/cli",
  "lib/vector-vrl/dnstap-parser",
  "lib/vector-vrl/doc-builder",
  "lib/vector-vrl/enrichment",
  "lib/vector-vrl/functions",
  "lib/vector-vrl/metrics",
  "lib/vector-vrl/tests",
  "lib/vector-vrl/web-playground",
  "tests/antithesis/harness",
  "vdev",
]

[workspace.lints.rust]
# 'cfg(tokio_unstable)' used in vector; 'cfg(ddsketch_extended)' used in vector-core
unexpected_cfgs = { level = "warn", check-cfg = ['cfg(tokio_unstable)', 'cfg(ddsketch_extended)'] }

[workspace.lints.clippy]
string_slice = "warn"
await_holding_lock = "warn"
let_underscore_must_use = "warn"

[workspace.dependencies]
antithesis-instrumentation = { version = "0.1", default-features = false, features = [] }
antithesis_sdk = { version = "0.2", default-features = false, features = [] }
anyhow = { version = "1.0.102", default-features = false, features = ["std"] }
arc-swap = { version = "1.8.2", default-features = false }
async-compression = { version = "0.4.42", default-features = false, features = ["tokio", "gzip"] }
async-stream = { version = "0.3.6", default-features = false }
async-trait = { version = "0.1.89", default-features = false }
axum = { version = "0.6.20", default-features = false }
base64 = { version = "0.22.1", default-features = false }
bytes = { version = "1.11.1", default-features = false, features = ["serde"] }
cfg-if = { version = "1.0.4", default-features = false }
chrono = { version = "0.4.44", default-features = false, features = ["clock", "serde"] }
chrono-tz = { version = "0.10.4", default-features = false, features = ["serde"] }
clap = { version = "4.5.60", default-features = false, features = ["derive", "error-context", "env", "help", "std", "string", "usage", "wrap_help"] }
clap_complete = "4.6.5"
colored = { version = "3.1.1", default-features = false }
const-str = { version = "1.1.0", default-features = false }
convert_case = { version = "0.8", default-features = false }
criterion = "0.8"
crossbeam-utils = { version = "0.8.21", default-features = false }
darling = { version = "0.20.11", default-features = false, features = ["suggestions"] }
dashmap = { version = "6.1.0", default-features = false }
derivative = { version = "2.2.0", default-features = false }
exitcode = { version = "1.1.2", default-features = false }
flate2 = { version = "1.1.2", default-features = false, features = ["zlib-rs"] }
futures = { version = "0.3.32", default-features = false, features = ["std"] }
futures-util = { version = "0.3.29", default-features = false }
glob = { version = "0.3.3", default-features = false }
hickory-proto = { version = "0.26.1", default-features = false, features = ["dnssec-ring"] }
humantime = { version = "2.3.0", default-features = false }
indexmap = { version = "2.11.0", default-features = false, features = ["serde", "std"] }
indoc = { version = "2.0.7" }
inventory = { version = "0.3" }
itertools = { version = "0.14.0", default-features = false, features = ["use_alloc"] }
libc = { version = "0.2", default-features = false, features = ["std"] }
metrics = "0.24.2"
metrics-tracing-context = { version = "0.17.0", default-features = false }
metrics-util = { version = "0.18.0", default-features = false, features = ["registry"] }
mlua = { version = "0.11", default-features = false, features = ["lua54", "send", "vendored"] }
nom = { version = "8.0.0", default-features = false }
ordered-float = { version = "4.6.0", default-features = false }
pastey = { version = "0.2", default-features = false }
pin-project = { version = "1.1.11", default-features = false }
proptest = { version = "1.11" }
proptest-derive = { version = "0.6.0" }
prost = { version = "0.12", default-features = false, features = ["std"] }
prost-build = { version = "0.12", default-features = false }
prost-reflect = { version = "0.14", features = ["serde"], default-features = false }
prost-types = { version = "0.12", default-features = false }
quickcheck = { version = "1.1.0" }
rand = { version = "0.9.2", default-features = false, features = ["small_rng", "thread_rng"] }
rand_distr = { version = "0.5.1", default-features = false }
rdkafka = { version = "0.39.0", default-features = false }
regex = { version = "1.12.3", default-features = false, features = ["std", "perf"] }
reqwest = { version = "0.11", features = ["json"] }
rust_decimal = { version = "1.40.0", default-features = false, features = ["std"] }
semver = { version = "1.0.28", default-features = false, features = ["serde", "std"] }
serde = { version = "1.0.219", default-features = false, features = ["alloc", "derive", "rc"] }
serde_json = { version = "1.0.150", default-features = false, features = ["preserve_order", "raw_value", "std"] }
serde_with = { version = "3.21.0", default-features = false, features = ["std", "macros", "chrono_0_4"] }
serde_yaml = { version = "0.9.34", default-features = false }
snafu = { version = "0.9.0", default-features = false, features = ["futures", "std"] }
socket2 = { version = "0.5.10", default-features = false }
tempfile = "3.27.0"
tokio = { version = "1.49.0", default-features = false }
tokio-stream = { version = "0.1.18", default-features = false }
tokio-test = "0.4.5"
tokio-tungstenite = { version = "0.20.1", default-features = false }
proc-macro2 = { version = "1", default-features = false }
quote = { version = "1", default-features = false }
syn = { version = "2", default-features = false }
toml = { version = "0.9.8", default-features = false, features = ["serde", "display", "parse"] }
tonic = { version = "0.11", default-features = false, features = ["transport", "codegen", "prost", "tls", "tls-roots", "gzip", "zstd"] }
tonic-build = { version = "0.11", default-features = false, features = ["transport", "prost"] }
tonic-health = { version = "0.11", default-features = false }
tonic-reflection = { version = "0.11", default-features = false, features = ["server"] }
tracing = { version = "0.1.44", default-features = false }
tracing-subscriber = { version = "0.3.22", default-features = false, features = ["fmt"] }
url = { version = "2.5.4", default-features = false, features = ["serde"] }
uuid = { version = "1.22.0", features = ["v4", "v7", "serde", "fast-rng"] }
vector-buffers = { path = "lib/vector-buffers" }
vector-config = { path = "lib/vector-config" }
vector-config-common = { path = "lib/vector-config-common" }
vector-config-macros = { path = "lib/vector-config-macros" }
vector-common-macros = { path = "lib/vector-common-macros" }
vector-lib = { path = "lib/vector-lib", default-features = false, features = ["vrl"] }
vector-vrl-category = { path = "lib/vector-vrl/category" }
vector-vrl-functions = { path = "lib/vector-vrl/functions", default-features = false }
vrl = { git = "https://github.com/vectordotdev/vrl.git", branch = "main", default-features = false, features = ["arbitrary", "cli", "test", "test_framework", "stdlib-base"] }
mock_instant = { version = "0.6" }
serial_test = { version = "3.4" }
strum = { version = "0.28", features = ["derive"] }

[dependencies]
cfg-if.workspace = true
reqwest.workspace = true
reqwest_13 = { package = "reqwest", version = "0.13", default-features = false, features = ["json", "native-tls", "rustls-no-provider"] }
clap.workspace = true
clap_complete.workspace = true
indoc.workspace = true
pastey.workspace = true
pin-project.workspace = true
proptest = { workspace = true, optional = true }
proptest-derive = { workspace = true, optional = true }
semver.workspace = true
snafu.workspace = true
uuid.workspace = true
vrl.workspace = true

# Internal libs
fakedata = { path = "lib/fakedata", optional = true }
tracing-limit = { path = "lib/tracing-limit" }
vector-common = { path = "lib/vector-common", default-features = false }
vector-lib.workspace = true
vector-config.workspace = true
vector-config-common.workspace = true
vector-config-macros.workspace = true
vector-vrl-functions = { workspace = true, features = ["vrl-metrics"] }
vector-vrl-metrics = { path = "lib/vector-vrl/metrics" }
loki-logproto = { path = "lib/loki-logproto", optional = true }

# Tokio / Futures
async-stream.workspace = true
async-trait.workspace = true
futures.workspace = true
tokio = { workspace = true, features = ["full"] }
tokio-openssl = { version = "0.6.5", default-features = false }
tokio-stream = { workspace = true, features = ["net", "sync", "time"] }
tokio-util = { version = "0.7", default-features = false, features = ["io", "time"] }
console-subscriber = { version = "0.4.1", default-features = false, optional = true }

# Tracing
tracing.workspace = true
tracing-core = { version = "0.1.26", default-features = false }
tracing-futures = { version = "0.2.5", default-features = false, features = ["futures-03"] }
tracing-subscriber = { workspace = true, features = ["ansi", "env-filter", "fmt", "json", "registry", "tracing-log"] }
tracing-tower = { git = "https://github.com/tokio-rs/tracing", default-features = false, rev = "e0642d949891546a3bb7e47080365ee7274f05cd" }

# Metrics
metrics.workspace = true
metrics-tracing-context.workspace = true

# AWS - Official SDK
aws-runtime = { version = "1.5.9", optional = true }
aws-config = { version = "1.8.13", default-features = false, features = ["behavior-version-latest", "credentials-process", "sso", "rt-tokio"], optional = true }
aws-credential-types = { version = "1.2.4", default-features = false, features = ["hardcoded-credentials"], optional = true }
aws-sdk-cloudwatch = { version = "1.102.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-cloudwatchlogs = { version = "1.116.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-elasticsearch = { version = "1.96.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-firehose = { version = "1.101.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-kinesis = { version = "1.99.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-kms = { version = "1.99.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-s3 = { version = "1.122.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-secretsmanager = { version = "1.99.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-sns = { version = "1.94.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-sdk-sqs = { version = "1.93.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }
aws-types = { version = "1.3.8", default-features = false, optional = true }

# The sts crate is needed despite not being referred to anywhere in the code because we need to set the
# `behavior-version-latest` feature. Without this we get a runtime panic when `auth.assume_role` authentication
# is configured.
aws-sdk-sts = { version = "1.73.0", default-features = false, features = ["behavior-version-latest", "rt-tokio"], optional = true }

# The `aws-sdk-sts` crate is needed despite not being referred to anywhere in the code because we need to set the
# `behavior-version-latest` feature. Without this we get a runtime panic when `auth.assume_role` authentication is configured.
aws-sigv4 = { version = "1.3.2", default-features = false, features = ["sign-http"], optional = true }

aws-smithy-async = { version = "1.2.5", default-features = false, features = ["rt-tokio"], optional = true }
aws-smithy-http = { version = "0.63", default-features = false, features = ["event-stream", "rt-tokio"], optional = true }
aws-smithy-runtime = { version = "1.8.3", default-features = false, features = ["client", "connector-hyper-0-14-x", "rt-tokio"], optional = true }
aws-smithy-runtime-api = { version = "1.7.3", default-features = false, optional = true }
aws-smithy-types = { version = "1.2.11", default-features = false, features = ["rt-tokio"], optional = true }

# Azure
azure_core = { version = "1.0", default-features = false, features = ["reqwest", "hmac_openssl"], optional = true }
azure_identity = { version = "1.0", default-features = false, features = ["client_certificate"], optional = true }

# Azure Storage
azure_storage_blob = { version = "1.0", default-features = false, optional = true }

# OpenDAL
opendal = { version = "0.54", default-features = false, features = ["services-webhdfs"], optional = true }

# Tower
tower = { version = "0.5.2", default-features = false, features = ["buffer", "limit", "retry", "timeout", "util", "balance", "discover"] }
tower-http = { version = "0.4.4", default-features = false, features = ["compression-full", "decompression-full", "trace"] }
# Serde
serde.workspace = true
serde-toml-merge = { version = "0.3.11", default-features = false }
serde_bytes = { version = "0.11.17", default-features = false, features = ["std"], optional = true }
serde_json.workspace = true
serde_with = { version = "3.14.0", default-features = false, features = ["macros", "std"] }
serde_yaml.workspace = true

# Messagepack
rmp-serde = { version = "1.3.0", default-features = false, optional = true }
rmpv = { version = "1.3.0", default-features = false, features = ["with-serde"], optional = true }

# Prost / Protocol Buffers
prost = { workspace = true, optional = true }
prost-reflect = { workspace = true, optional = true }
prost-types = { workspace = true, optional = true }

# Databricks Zerobus
databricks-zerobus-ingest-sdk = { version = "2.3.0", optional = true, features = ["arrow-flight"] }

# GCP
goauth = { version = "0.16.0", optional = true }
smpl_jwt = { version = "0.8.0", default-features = false, optional = true }

# AMQP
lapin = { version = "4.3.0", default-features = false, features = ["tokio", "native-tls"], optional = true }
async-rs = { version = "0.8", default-features = false, features = ["tokio"], optional = true }
deadpool = { version = "0.13.0", default-features = false, features = ["managed", "rt_tokio_1"], optional = true }

# Opentelemetry

hex = { version = "0.4.3", default-features = false, optional = true }

# GreptimeDB
greptimedb-ingester = { version = "0.17.0", default-features = false, optional = true }

# External libs
arc-swap = { workspace = true, default-features = false, optional = true }
async-compression = { workspace = true, features = ["zstd"], optional = true }
arrow = { version = "58.2.0", default-features = false, features = ["ipc"], optional = true }
arrow-schema = { version = "58.2.0", default-features = false, optional = true }
parquet = { version = "58.2.0", default-features = false, features = [
  "arrow",
  "snap",
  "zstd",
  "lz4",
  "flate2-rust_backened",
], optional = true }
axum = { version = "0.6.20", default-features = false }
base64 = { workspace = true, optional = true }
bloomy = { version = "1.2.0", default-features = false, optional = true }
bollard = { version = "0.20", default-features = false, features = ["pipe", "ssl", "chrono"], optional = true }
bytes = { workspace = true, features = ["serde"] }
bytesize = { version = "2.0.1", default-features = false }
chrono.workspace = true
chrono-tz.workspace = true
colored.workspace = true
csv = { version = "1.3", default-features = false }
databend-client = { version = "0.28.0", default-features = false, features = ["rustls"], optional = true }
derivative.workspace = true
dirs-next = { version = "2.0.0", default-features = false, optional = true }
dyn-clone = { version = "1.0.20", default-features = false }
encoding_rs = { version = "0.8.35", default-features = false, features = ["serde"] }
enum_dispatch = { version = "0.3.13", default-features = false }
evmap = { version = "10.0.2", default-features = false, optional = true }
evmap-derive = { version = "0.2.0", default-features = false, optional = true }
exitcode.workspace = true
flate2.workspace = true
futures-util.workspace = true
glob.workspace = true
governor = { version = "0.10.0", default-features = false, features = ["dashmap", "jitter", "std"], optional = true }
h2 = { version = "0.4.11", default-features = false, optional = true }
hash_hasher = { version = "2.0.4", default-features = false }
hashbrown = { version = "0.14.5", default-features = false, optional = true, features = ["ahash"] }
headers = { version = "0.3.9", default-features = false }
hostname = { version = "0.4.0", default-features = false }
