    fn test_format_rdata(raw_data: &str, code: u16, expected_output: &str) {
        let raw_rdata = BASE64
            .decode(raw_data.as_bytes())
            .expect("Invalid base64 encoded rdata.");
        let mut decoder = BinDecoder::new(&raw_rdata);
        let record = Record::from_rdata(
            Name::new(),
            1,
            RData::read(
                &mut decoder,
                RecordType::from(code),
                Restrict::new(raw_rdata.len() as u16),
            )
            .unwrap(),
        );
        let rdata_text = DnsMessageParser::new(Vec::<u8>::new())
            .parse_dns_record(&record)
            .map(|r| r.rdata);
        assert!(rdata_text.is_ok());
        assert_eq!(expected_output, rdata_text.unwrap().unwrap());
    }

    fn test_format_rdata_with_compressed_domain_names(
        raw_message: &str,
        raw_data_encoded: &str,
        code: u16,
        expected_output: &str,
    ) {
        let raw_message = BASE64
            .decode(raw_message.as_bytes())
            .expect("Invalid base64 encoded raw message.");
        let raw_message_len = raw_message.len();
        let mut message_parser = DnsMessageParser::new(raw_message);
        let raw_rdata = BASE64
            .decode(raw_data_encoded.as_bytes())
            .expect("Invalid base64 encoded raw rdata.");
        for i in 1..=2 {
            let record_rdata = NULL::with(raw_rdata.clone());
            let rdata_text = message_parser.format_unknown_rdata(code, &record_rdata);
            assert!(rdata_text.is_ok());
            assert_eq!(expected_output, rdata_text.unwrap().0.unwrap());
            assert_eq!(
                raw_message_len + i * raw_rdata.len(),
                message_parser
                    .raw_message_for_rdata_parsing()
                    .unwrap()
                    .len()
            );
        }
    }
}

use hickory_proto::{
    ProtoError,
    serialize::binary::{BinDecodable, BinDecoder, BinEncodable, BinEncoder, DecodeError},
};

pub const EDE_OPTION_CODE: u16 = 15u16;

#[derive(Debug, Clone)]
pub struct EDE {
    info_code: u16,
    extra_text: Option<String>,
}

impl EDE {
    pub fn new(info_code: u16, extra_text: Option<String>) -> Self {
        Self {
            info_code,
            extra_text,
        }
    }

    // https://www.iana.org/assignments/dns-parameters/dns-parameters.xhtml#extended-dns-error-codes
    pub fn purpose(&self) -> Option<&str> {
        match self.info_code {
            0 => Some("Other Error"),
            1 => Some("Unsupported DNSKEY Algorithm"),
            2 => Some("Unsupported DS Digest Type"),
            3 => Some("Stale Answer"),
            4 => Some("Forged Answer"),
            5 => Some("DNSSEC Indeterminate"),
            6 => Some("DNSSEC Bogus"),
            7 => Some("Signature Expired"),
            8 => Some("Signature Not Yet Valid"),
            9 => Some("DNSKEY Missing"),
            10 => Some("RRSIGs Missing"),
            11 => Some("No Zone Key Bit Set"),
            12 => Some("NSEC Missing"),
            13 => Some("Cached Error"),
            14 => Some("Not Ready"),
            15 => Some("Blocked"),
            16 => Some("Censored"),
            17 => Some("Filtered"),
            18 => Some("Prohibited"),
            19 => Some("Stale NXDomain Answer"),
            20 => Some("Not Authoritative"),
            21 => Some("Not Supported"),
            22 => Some("No Reachable Authority"),
            23 => Some("Network Error"),
            24 => Some("Invalid Data"),
            25 => Some("Signature Expired before Valid"),
            26 => Some("Too Early"),
            27 => Some("Unsupported NSEC3 Iterations Value"),
            28 => Some("Unable to conform to policy"),
            29 => Some("Synthesized"),
            30 => Some("Invalid Query Type"),
            _ => None,
        }
    }

    pub fn info_code(&self) -> u16 {
        self.info_code
    }

    pub fn extra_text(&self) -> Option<String> {
        self.extra_text.clone()
    }
}

impl BinEncodable for EDE {
    fn emit(&self, encoder: &mut BinEncoder<'_>) -> Result<(), ProtoError> {
        encoder.emit_u16(self.info_code)?;
        if let Some(extra_text) = &self.extra_text {
            encoder.emit_vec(extra_text.as_bytes())?;
        }
        Ok(())
    }
}

impl<'a> BinDecodable<'a> for EDE {
    fn read(decoder: &mut BinDecoder<'a>) -> Result<Self, DecodeError> {
        let info_code = decoder.read_u16()?.unverified();
        let extra_text = if decoder.is_empty() {
            None
        } else {
            Some(
                String::from_utf8(decoder.read_vec(decoder.len())?.unverified())
                    .map_err(DecodeError::Utf8)?,
            )
        };
        Ok(Self {
            info_code,
            extra_text,
        })
    }
}

